import sys
from itertools import permutations

def has_hamiltonian_path(n, edges):
    graph = {i: set() for i in range(1, n + 1)}
    for v, u in edges:
        graph[v].add(u)
        graph[u].add(v)

    def is_valid_path(path):
        for i in range(len(path) - 1):
            if path[i + 1] not in graph[path[i]]:
                return False
        return True

    for perm in permutations(range(1, n + 1)):
        if is_valid_path(perm):
            return True
    return False

def main():
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    edges = []
    for _ in range(m):
        vi = int(input[index])
        ui = int(input[index + 1])
        edges.append((vi, ui))
        index += 2
    print("Yes" if has_hamiltonian_path(n, edges) else "No")

main()
